/**
 * PLACEHOLDER — DELETE WHEN `clients/ts/index.d.ts` (generated by openapi-typescript from
 * api/openapi.yaml, task A2) LANDS. Then change the one line in `./schema.ts` to re-export from the
 * generated file and fix whatever the compiler reports.
 *
 * Hand-written from backend plan §6/§8 and web plan §7. Everything here is PROVISIONAL; the OpenAPI
 * spec is authoritative. Field names marked (assumed) are not specified anywhere yet.
 */

/** Open enum: unknown strings must never crash a screen (web plan §4). */
// (a plain `string`: openapi-fetch's response type helpers mangle the `T | (string & {})` form)
// eslint-disable-next-line @typescript-eslint/no-unused-vars
type OpenEnum<_T extends string> = string

export interface components {
  schemas: {
    AuthMethod: {
      id: OpenEnum<'password' | 'sms_otp' | 'magic_link'> // 'oidc:<provider>' entries appear later
      label_key?: string
      icon?: string
    }
    /** GET /.well-known/openbekci.json (backend §8, overview §6.8). */
    DiscoveryDocument: {
      instance_id: string
      instance_name: string
      api_base_url: string
      api_versions: string[]
      server_version: string
      sdk_version: string | null
      min_app_version?: { android: string; ios: string }
      auth_methods: components['schemas']['AuthMethod'][]
      push?: { relay_ids: string[]; unified_push: boolean }
      packs: string[]
      branding?: { logo_url?: string; primary_color?: string }
    }
    Permission: string
    /** One effective permission; absent site_ids/block_ids means organization-wide. (assumed shape) */
    EffectivePermission: {
      permission: components['schemas']['Permission']
      site_ids?: string[]
      block_ids?: string[]
    }
    Site: { id: string; name: string; timezone: string; currency: string }
    MeOrganization: {
      id: string
      name: string
      default_locale?: string // (assumed) organization default for locale resolution
      roles: string[]
      permissions: components['schemas']['EffectivePermission'][]
      sites?: components['schemas']['Site'][] // (assumed) convenience for tz/currency
    }
    Occupancy: {
      id: string
      organization_id: string
      site_id: string
      unit_id: string
      unit_label: string
      kind: OpenEnum<'owner' | 'tenant' | 'household'>
      may_see_money: boolean
    }
    /** GET /v1/me */
    Me: {
      user: {
        id: string
        display_name: string
        email?: string | null
        phone?: string | null
        locale?: string | null
        platform_admin?: boolean // (assumed) gates /platform
      }
      organizations: components['schemas']['MeOrganization'][]
      occupancies: components['schemas']['Occupancy'][]
    }
    /** RFC 9457 problem+json as the backend emits it (code enum: backend §8). */
    Problem: {
      type?: string
      title?: string
      status: number
      detail?: string
      code?: OpenEnum<
        | 'validation_failed'
        | 'not_found'
        | 'conflict'
        | 'version_conflict'
        | 'idempotency_mismatch'
        | 'locked_period'
        | 'insufficient_permission'
        | 'reauth_required'
        | 'mfa_required'
        | 'invalid_grant'
        | 'rate_limited'
        | 'pack_error'
        | 'site_offboarded'
      >
      errors?: { field: string; code: string; message?: string }[]
      request_id?: string
    }
    /** PROVISIONAL: POST /v1/auth/session is defined by a later backend task. */
    SessionRequest: {
      method: 'password' | 'sms_otp' | 'magic_link'
      /** email or phone */
      identifier: string
      password?: string
      /** SMS one-time code; omitted on the first step, which asks the server to send one */
      code?: string
      client?: 'web'
    }
  }
}

type Json<T> = { content: { 'application/json': T } }
type ProblemResponse = Json<components['schemas']['Problem']>

export interface paths {
  '/.well-known/openbekci.json': {
    get: {
      parameters: { query?: never; header?: never; path?: never; cookie?: never }
      requestBody?: never
      responses: { 200: Json<components['schemas']['DiscoveryDocument']> & { headers: object } }
    }
  }
  '/v1/me': {
    get: {
      parameters: { query?: never; header?: never; path?: never; cookie?: never }
      requestBody?: never
      responses: {
        200: Json<components['schemas']['Me']> & { headers: object }
        401: ProblemResponse & { headers: object }
      }
    }
  }
  '/v1/auth/session': {
    post: {
      parameters: { query?: never; header?: never; path?: never; cookie?: never }
      requestBody: Json<components['schemas']['SessionRequest']>
      responses: {
        /** 204/200: session cookie set. 202: a code was sent, ask for it. */
        200: { headers: object; content?: never }
        202: { headers: object; content?: never }
        401: ProblemResponse & { headers: object }
        422: ProblemResponse & { headers: object }
        429: ProblemResponse & { headers: object }
      }
    }
    delete: {
      parameters: { query?: never; header?: never; path?: never; cookie?: never }
      requestBody?: never
      responses: { 204: { headers: object; content?: never } }
    }
  }
}
